/* cppi::9bca5948852332ee5d84566921510b1097d89dc4483aab85f32431e3ba203c4f */
SELECT DISTINCT trim(
        element_at(
            split(
                -- Handle comma in job title
                element_at(split(business_title, ','), 1),
                '&' -- Handle & in job title like Senior Managing Director & Head of Private Equity
            ),
            1
        )
    ) as job_level
FROM df_trusted_prod.workday_cppib_employee
ORDER BY job_level ASC

